def e(value):
    return escape(str(value), quote=True)


def n(value, places=1):
    if value is None:
        return 'Not reported'
    value = Decimal(str(value)).quantize(Decimal('1').scaleb(-places), rounding=ROUND_HALF_UP)
    return format(value.normalize(), 'f')


def get(market, chain, name):
    rows = [r for r in RECORDS if (r['market'], r['chain'], r['name']) == (market, chain, name)]
    assert len(rows) == 1, (market, chain, name)
    row = rows[0]
    assert row['verificationStatus'] in ('official-table-reviewed', 'official-page-reviewed')
    USED[row['id']] = row
    return row


def add(name, rows, serving):
    assert len({r['market'] for r in rows}) == 1
    result = {'name': name, 'serving': serving, 'market': rows[0]['market'], 'calculated': True, 'componentIds': [r['id'] for r in rows]}
    for field in ('cal', 'p', 'c', 'fat', 'f', 'na', 'sugar'):
        result[field] = None if any(r.get(field) is None for r in rows) else float(sum(Decimal(str(r[field])) for r in rows))
    result['salt'] = None if any(r.get('nativeNutrients', {}).get('salt') is None for r in rows) else float(sum(Decimal(str(r['nativeNutrients']['salt'])) for r in rows))
    return result


def val(row, field):
    return row.get('salt', row.get('nativeNutrients', {}).get('salt')) if field == 'salt' else row.get(field)


def table(rows, caption, fields=('cal', 'p', 'c', 'fat'), labels=None):
    headings = {'cal': 'kcal', 'p': 'Protein (g)', 'c': 'Carbs (g)', 'fat': 'Fat (g)', 'f': 'Fibre (g)', 'na': 'Sodium (mg)', 'salt': 'Salt (g)', 'sugar': 'Total sugars (g)'}
    body = []
    for index, row in enumerate(rows):
        name = labels[index] if labels else row['name']
        body.append('<tr><th scope="row">' + e(name) + '<small class="table-portion">' + e(row['serving']) + '</small></th>' + ''.join('<td>' + n(val(row, f), 2 if f == 'salt' else 1) + '</td>' for f in fields) + '</tr>')
    return '<div class="table-wrap" role="region" tabindex="0" aria-label="' + e(caption) + '"><table><caption>' + e(caption) + '</caption><thead><tr><th scope="col">Order and portion</th>' + ''.join('<th scope="col">' + headings[f] + '</th>' for f in fields) + '</tr></thead><tbody>' + ''.join(body) + '</tbody></table></div>'


def figure(rows, labels, caption, field='cal'):
    """Original accessible numeric artwork; no restaurant photography or logo rights implied."""
    assert len(rows) == len(labels)
    title_id = 'chart-' + hashlib.sha256(caption.encode()).hexdigest()[:10]
    unit = {'cal': 'kcal', 'p': 'g protein', 'salt': 'g salt'}[field]
    maximum = max(float(val(r, field)) for r in rows)
    height = 54 + 64 * len(rows)
    bars = []
    for index, (row, label) in enumerate(zip(rows, labels)):
        value = float(val(row, field))
        width = value / maximum * 370 if maximum else 0
        y = 46 + index * 64
        bars.append(f'<text x="20" y="{y}" fill="currentColor" font-size="18">{e(label)}</text><rect x="20" y="{y+11}" width="{width:.2f}" height="12" rx="6" fill="var(--green,#286a49)"/><text x="{max(30,width+30):.2f}" y="{y+24}" fill="currentColor" font-size="17">{n(value)} {unit}</text>')
    return f'<figure class="article-data-figure"><svg class="article-data-chart" viewBox="0 0 620 {height}" width="620" height="{height}" role="img" aria-labelledby="{title_id}"><title id="{title_id}">{e(caption)}</title>{"".join(bars)}</svg><figcaption>{e(caption)}. Bars start at zero; figures use the portions in the table.</figcaption></figure>'


def compare(rows, label):
    pairs = [('item', 'order:' + r['market'] + ':' + r['id']) for r in rows]
    return '<p><a href="/compare-foods.html?' + e(urlencode(pairs + [('basis', 'portions')])) + '">' + e(label) + '</a></p>'


def source(title, url, notes, checked=DATE):
    return {'title': title, 'url': url, 'checked_on': checked, 'notes': notes}


def spaced(text):
    """Keep nutrient notation and dates readable without touching URLs or HTML attributes."""
    parts = re.split(r'(<[^>]*>|&(?:#\d+|#[xX][0-9A-Fa-f]+|\w+);)', text)
    for index in range(0, len(parts), 2):
        part = parts[index]
        part = re.sub(r'([A-Za-z])(\d)', r'\1 \2', part)
        part = re.sub(r'(\d)([A-Za-z])', r'\1 \2', part)
        part = re.sub(r'\b(kcal|mg|kg|g)(?=(?:protein|fibre|fiber|fat|carbs|salt|sodium|total|hot|iced|higher|lower|above|below|more|less|portion|versus|and|with|before|after|for|or|per|Tall|Grande|Small|Medium|Large))', r'\1 ', part)
        part = re.sub(r'([;:])(?=\S)', r'\1 ', part)
        part = re.sub(r'(?<!\d),(?=\S)|,(?=[A-Za-z])', ', ', part)
        part = re.sub(r'\s*([×÷=])\s*', r' \1 ', part)
        part = re.sub(r'(?<=\d)\s*\+\s*(?=\d)', ' + ', part)
        part = re.sub(r'\b(more|less|fewer|total)(protein|fibre|fiber|fat|carbs|salt|sodium|sugars|kcal)\b', r'\1 \2', part)
        parts[index] = part
    return ''.join(parts)


def article(slug, title, description, category, country, question, answer, body, rows, sources, related, overlap, distinct, query):
    for item in sources:
        item['title'], item['notes'] = spaced(item['title']), spaced(item['notes'])
    return {'slug': slug, 'title': title, 'description': description, 'category': category, 'country': country, 'published': DATE, 'modified': DATE, 'question': question, 'answer': spaced(answer), 'body_html': spaced(body), 'sources': sources, 'related': related, 'visual': {'kind': 'Original source-based SVG chart and accessible comparison table', 'description': 'GetMacros-authored numeric artwork. No third-party food photograph or logo republished.'}, 'review': {'status': 'source-and-arithmetic-reviewed; awaiting integrated browser and publication checks', 'scope': 'AI editorial review against named official source portions, source identity checks and decimal arithmetic tests. No medical or dietitian review claimed.', 'limitations': 'Snapshot of named recipes and portions; not every live menu option or branch. Published rounded values can differ from a hand-prepared serving.'}, 'source_record_ids': [r['id'] for r in rows if r.get('id')], 'search_observations': [{'query': query, 'observation': spaced(SEARCH_NOTES[slug]), 'source_url': sources[0]['url'], 'checked_on': DATE, 'measured_volume': None}], 'overlap_review': {'existing': overlap, 'distinct_value': distinct}}


def articles():
    output = []
    # 1: Canadian breakfast formats. No fabricated size extrapolation for Double Double.
    names = ['Egg & Cheese English Muffin', 'Egg & Cheese Homestyle Biscuit', 'Bacon English Muffin', 'Sausage English Muffin', "Bacon Farmer's Wrap", "Sausage Farmer's Wrap"]
    rows = [get('CA', 'Tim Hortons', name) for name in names]
    muffin, biscuit, bacon, sausage, wrap_b, wrap_s = rows
    hash_brown = get('CA', 'Tim Hortons', 'Hash Brown')
    coffee = get('CA', 'Tim Hortons', 'Original Blend Coffee - Medium')
    breakfast = add('Egg & Cheese English Muffin + Hash Brown + medium black coffee', [muffin, hash_brown, coffee], '1 of each named item; no cream or sugar')
    body = '''<h2>Choose the bread before comparing the filling</h2><p>The egg-and-cheese English muffin and homestyle biscuit both list 14 g protein. The biscuit lists 350 kcal against the muffin’s 270: an 80 kcal difference without more listed protein. Carbohydrate changes from 27 g to 33 g, fat from 12 g to 18 g, and sodium from 500 mg to 720 mg.</p><p>This comparison is between the complete named sandwiches. It does not isolate the bread’s nutrition, because the published servings are finished recipes, not a controlled bread-only swap.</p>''' + table(rows, 'Tim Hortons Canada: one listed breakfast food, before sides or drinks') + '''<h2>What changes with bacon or sausage?</h2><p>For the English muffins in this Canadian guide, bacon lists 330 kcal and 17 g protein; sausage lists 450 kcal and 19 g protein. Choosing sausage adds 120 kcal and 2 g protein relative to the bacon sandwich. It does not follow that the sausage version is higher in every nutrient: sodium is 680 mg versus 710 mg for bacon.</p><h2>A Farmer’s Wrap is another recipe</h2><p>The Bacon Farmer’s Wrap is 520 kcal and 19 g protein; the Sausage Farmer’s Wrap is 640 kcal and 21 g protein. Both exceed their named English-muffin counterparts by 190 kcal in this edition. Use the wrap’s complete row when logging it. Do not add a hypothetical hash brown inside the wrap again, or subtract an assumed amount for an omitted sauce.</p>''' + figure([muffin, biscuit, bacon, sausage], ['Egg & cheese muffin', 'Egg & cheese biscuit', 'Bacon muffin', 'Sausage muffin'], 'Calories in four Canadian breakfast sandwiches') + '''<h2>Count the breakfast you actually ordered</h2><p>An egg-and-cheese English muffin, a separate Hash Brown and a medium Original Blend Coffee without additions total 394 kcal and 15 g protein: 270 + 120 + 4 kcal. The table below is our calculation, not a restaurant-advertised combo. Cream, sugar, a different drink or another side changes it.</p>''' + table([breakfast], 'GetMacros calculation: sandwich, side and named black coffee') + '''<h2>Use the Canadian edition</h2><p>These values come from the July 2026 Canadian nutrition guide, retained with its exact item names. It does not supply gram weights for these selected records, so an English muffin and a wrap are compared as named orders rather than equal weights. Check the current local menu before ordering; no U.S. breakfast recipe is substituted here.</p>''' + compare([muffin, biscuit, bacon], 'Compare the Canadian sandwiches')
    output.append(article('tim-hortons-canada-breakfast-muffin-biscuit-wrap', 'Tim Hortons Canada breakfast: muffin, biscuit or Farmer’s Wrap?', 'Compare six Canadian Tim Hortons breakfast recipes, then calculate an English muffin with a hash brown and black coffee.', 'Breakfast', 'CA', 'Which Tim Hortons Canadian breakfast format changes calories and protein most?', 'The Egg & Cheese English Muffin lists 270 kcal and 14 g protein; the biscuit has 350 kcal and the same protein. A Bacon Farmer’s Wrap is a different, larger listed order at 520 kcal and 19 g protein.', body, rows + [hash_brown, coffee], [source('Tim Hortons Canada nutrition guide · July 2026', muffin['source'], 'Canadian July2026 edition, exact named breakfast recipes and drinks; no inferred customizations.'), source('Tim Hortons official Canadian nutrition and allergen guidance', 'https://help.timhortons.ca/hc/en-ca/articles/35734906287643-Where-can-I-view-the-nutrition-and-allergen-information-for-Tim-Hortons-menu-items', 'Confirms official item and allergen information is provided through the Canadian website/app.')], [{'label': 'Browse Tim Hortons Canada', 'href': '/ca/en/restaurants/tim-hortons/'}, {'label': 'Log this breakfast', 'href': '/food-diary.html?market=CA'}], ['tim-hortons-canada-protein-latte-vs-latte.html', 'fast-food-breakfast-protein-comparison.html'], 'Canadian breakfast format and full selected breakfast arithmetic, not an existing protein-latte or U.S. breakfast comparison.', 'Tim Hortons Canada breakfast sandwich calories protein English muffin biscuit'))

    # 2: Harvey’s complete-order decision, not another burger-only ranking.
    burger = get('CA', 'Harvey’s', 'Original Burger')
    fries = get('CA', 'Harvey’s', 'Fries (Regular)')
    large = get('CA', 'Harvey’s', 'Fries (Large)')
    rings = get('CA', 'Harvey’s', 'Onion Rings (Regular)')
    rows = [burger, fries, rings, large]
    totals = [add('Original Burger + regular fries', [burger, fries], '1 burger + 154 g fries'), add('Original Burger + regular onion rings', [burger, rings], '1 burger + 85 g onion rings'), add('Original Burger + large fries', [burger, large], '1 burger + 198 g fries')]
    body = '''<h2>Keep the burger fixed</h2><p>Harvey’s lists the Original Burger at 380 kcal and 17 g protein for a 145 g serving. A regular side is a separate food: fries weigh 154 g, while onion rings weigh 85 g. Calling both “regular” does not make their portions equal.</p>''' + table(rows, 'Harvey’s Canada: the components before combining', ('cal', 'p', 'c', 'fat', 'f', 'na')) + '''<h2>Fries or onion rings with the same main?</h2><p>Adding regular fries produces a calculated food total of 810 kcal and 23 g protein. With regular onion rings, it is 680 kcal and 21 g protein. The ring order has 130 fewer kcal, but also 4 g less fibre: 3 g versus 7 g for the complete burger-and-fries calculation.</p><p>This does not establish that onion rings are lighter gram for gram. The portions differ by 69 g. It answers the practical question of choosing the named side sold with your order.</p>''' + figure(totals, ['Burger + regular fries', 'Burger + regular rings', 'Burger + large fries'], 'The selected side changes the whole food order') + table(totals, 'Calculated burger-and-side totals; drinks and optional toppings excluded', ('cal', 'p', 'c', 'fat', 'f', 'na')) + '''<h2>What does a larger fries serving add?</h2><p>The large fries row is 550 kcal and 7 g protein. Moving from regular to large fries adds 120 kcal and 1 g protein to this order, making the total 930 kcal and 24 g protein. A larger portion does not increase every field by the same rounded amount.</p><h2>Your toppings and drink still matter</h2><p>Harvey’s allows customized toppings, but this calculation starts with its published Original Burger row. It is not permission to treat every topping as zero or to add cheese twice to a burger row that already includes cheese. Match the named main, then use separately supported additions.</p><p>No drink, dip, additional cheese or other customization is included here. If you cannot identify the drink’s size and recipe, save a food subtotal with the drink still unknown rather than claiming that the full order is known.</p><h2>What the numbers can tell you</h2><p>Use calories, protein, fibre and sodium together for the portion you want. They do not produce an overall health score or allergy guarantee. Harvey’s official page warns about cross-contact; ingredient and allergy questions belong with the restaurant.</p>''' + compare([fries, rings], 'Compare the two actual regular side portions')
    output.append(article('harveys-canada-burger-fries-onion-rings-order', 'Harvey’s Canada: an Original Burger with fries or onion rings', 'Calculate Harvey’s Original Burger with regular fries, onion rings or large fries, keeping portions and optional additions clear.', 'Meal comparisons', 'CA', 'What does the side add to a Harvey’s Original Burger order?', 'An Original Burger with regular fries totals 810 kcal and 23 g protein. With regular onion rings, it totals 680 kcal and 21 g protein. These are food-component calculations, without a drink or extra toppings.', body, rows, [source('Harvey’s Canada official nutrition and allergen table', burger['source'], 'Official Canadian Original Burger, fries and onion-ring values and named serving weights. Optional garnishes, sauces and drinks are not automatically included.')], [{'label': 'Harvey’s Canadian menu selection', 'href': '/ca/en/restaurants/harvey-s/'}, {'label': 'Build a complete order', 'href': '/compare-complete-restaurant-orders.html?market=CA'}], ['harveys-original-angus-veggie-burger-comparison.html'], 'The existing article compares burger recipes; this guide fixes one main and quantifies side portions and unfinished drink/topping boundaries.', 'Harveys burger fries onion rings calories Canada complete meal'))

    # 3: One substantial breakfast guide includes the drink, avoiding two overlapping pages.
    rows = [get('GB', 'Greggs', x) for x in ['Omelette Breakfast Baguette', 'Bacon Breakfast Baguette', 'Sausage Breakfast Baguette', 'Bacon & Sausage Breakfast Baguette']]
    omelette, bacon, sausage, both = rows
    americano = get('GB', 'Greggs', 'Americano Regular')
    latte = get('GB', 'Greggs', 'Latte Regular')
    drinks = [add('Bacon baguette + regular Americano', [bacon, americano], '1 named baguette + 1 regular drink'), add('Bacon baguette + regular Latte', [bacon, latte], '1 named baguette + 1 regular drink')]
    body = '''<h2>Four baguettes, four actual recipes</h2><p>Greggs’ Omelette Breakfast Baguette is 441 kcal and 21 g protein. Bacon is 462 kcal and 26 g protein, sausage is 543 kcal and 24 g protein, and bacon with sausage is 550 kcal and 29 g protein. A filling’s name alone does not predict which complete sandwich has more protein.</p>''' + table(rows, 'Greggs breakfast baguettes: one whole published portion', ('cal', 'p', 'c', 'fat', 'salt')) + '''<h2>The closest calorie pair is not the same protein pair</h2><p>The omelette and bacon baguettes differ by 21 kcal, while bacon lists 5 g more protein. The sausage baguette is 81 kcal above the bacon version yet lists 2 g less protein. These are finished orders with different amounts and ingredients, not equal servings of bacon, egg and sausage.</p><p>The bacon-and-sausage baguette is only 7 kcal above the sausage baguette in this guide. It is not calculated by adding the entire bacon baguette to the entire sausage baguette. Doing that would count two baguettes and misrepresent the recipe.</p>''' + figure(rows, ['Omelette', 'Bacon', 'Sausage', 'Bacon & sausage'], 'Protein in one named Greggs breakfast baguette', 'p') + '''<h2>Include the coffee you choose</h2><p>A regular Americano adds 11 kcal and a regular Latte adds 114 kcal in the same guide. With the bacon baguette, those selected breakfast totals become 473 kcal and 576 kcal respectively, before any extra sugar or other additions. The difference is the drink recipe, not the baguette.</p>''' + table(drinks, 'Calculated breakfasts with the same bacon baguette') + '''<h2>Salt and size provide another useful view</h2><p>Greggs publishes salt in grams: 1.6 g for the omelette baguette, 2.6 g for bacon or sausage and 3.1 g for bacon-and-sausage. These are not sodium grams. GetMacros can convert salt to sodium for a common display, but the table above retains the restaurant’s original salt unit.</p><p>The source’s size column is labelled g/ml. Keep the named portion rather than silently calling every listed number a weighed gram amount. Scottish Lorne recipes and hospital-shop entries are separate records, and branch stock and breakfast hours should be checked locally.</p><h2>Log the whole named sandwich once</h2><p>Choose the baguette entry that matches the filling. Add your own drink, and check whether a requested condiment is included or separately supported. Do not turn a menu’s suggested ketchup or brown sauce into an invented gram amount.</p>''' + compare([bacon, sausage, both], 'Compare the three meat-filled baguettes')
    output.append(article('greggs-breakfast-baguette-calories-protein', 'Greggs breakfast baguettes: calories, protein and your coffee', 'Compare four Greggs breakfast baguettes and two complete breakfast examples with named regular coffees.', 'Breakfast', 'GB', 'Which Greggs breakfast baguette fits the portion and protein you want?', 'Bacon lists 462 kcal and 26 g protein; sausage lists 543 kcal and 24 g. A Bacon & Sausage Breakfast Baguette lists 550 kcal and 29 g protein, before a drink.', body, rows + [americano, latte], [source('Greggs official nutrition guide', bacon['source'], 'September2026 official portion table, including the source’s g/ml size-column label.'), source('Greggs Bacon and Sausage Breakfast Baguette', 'https://www.greggs.com/menu/product/bacon-and-sausage-breakfast-baguette-1000723', 'Official product page independently confirms208.5g,550kcal,29gprotein,63gcarbs,20gfat,3.1gsalt.')], [{'label': 'Browse the Greggs menu selection', 'href': '/gb/en/restaurants/greggs/'}, {'label': 'Find a UK breakfast', 'href': '/restaurant-meal-finder.html?market=GB&meal=breakfast'}], ['greggs-sausage-roll-vs-vegan-roll-nutrition.html', 'breakfast-drinks-and-add-ons.html'], 'Exact current Greggs baguette recipes plus quantified coffee choices, rather than pastry comparison or a generic add-ons explanation.', 'Greggs breakfast baguette calories protein'))

    # 4: Sauce and format, compared using full published recipes.
    rows = [get('GB', 'KFC', x) for x in ['Fillet Burger', 'Zinger Burger', 'Smokey BBQ Twister', 'Sweet Chilli Twister', 'Kentucky Mayo Twister', 'Supercharger Twister']]
    body = '''<h2>A wrap is not automatically lower in calories</h2><p>KFC’s UK Fillet Burger lists 463 kcal and 28.8 g protein. All four Twisters shown here list more calories per named item: 482–548 kcal. Their protein values are close to the Fillet Burger’s, ranging from 28.4 to 29.1 g.</p>''' + table(rows, 'KFC UK: individual burgers and named Twister recipes', ('cal', 'p', 'c', 'fat', 'salt')) + '''<h2>What changes between the Twisters?</h2><p>The Smokey BBQ Twister has 482 kcal, while the Supercharger Twister has 548 kcal: 66 kcal apart. Protein differs by just 0.4 g, from 28.7 to 29.1 g. Fat differs more, from 17.4 to 26 g. If you want a lower-calorie choice among these specific wraps, the sauce recipe matters more than the small protein difference.</p><p>Sweet Chilli lists 11 g total sugars; Kentucky Mayo lists 5.1 g. That does not make either sauce a universal “better” choice. Read the whole recipe and the nutrient you care about, rather than treating a sweet or creamy name as a nutrition rule.</p>''' + figure(rows[2:], ['Smokey BBQ', 'Sweet Chilli', 'Kentucky Mayo', 'Supercharger'], 'Calories in the four named Twister recipes') + '''<h2>Fillet and Zinger are different chicken recipes</h2><p>The Zinger Burger is 468 kcal and 23 g protein. Its calories are close to the Fillet Burger’s 463 kcal, but protein is 5.8 g lower. A five-calorie gap does not mean the two recipes have identical macros or ingredients.</p><p>Salt also differs: 2.2 g for Fillet and 2 g for Zinger, compared with 2.6 g for each Twister in this source. Salt is retained in grams; it is not sodium in milligrams.</p><h2>Keep a Twister separate from a Twister meal</h2><p>The official ordering page can present a Twister Wrap Meal, but the nutrition rows used here are the individual wraps. Fries, a drink, a dip or a side salad need their own matching portions. Do not call 520 kcal the total for every Kentucky Mayo Twister meal.</p><h2>What remains unknown?</h2><p>The source does not report fibre for these selected rows or a gram weight usable for an equal-weight comparison. We therefore compare the actual named orders and leave fibre unknown. Ingredients, allergies and local availability need the current restaurant information; none is inferred from these calorie totals.</p>''' + compare([rows[0], rows[2], rows[4]], 'Compare the Fillet Burger and two Twisters')
    output.append(article('kfc-uk-burger-twister-wrap-nutrition', 'KFC UK: Fillet Burger, Zinger or a Twister wrap?', 'Compare six KFC UK burgers and wraps by calories, protein, fat and salt, with the meal components kept separate.', 'Eating out', 'GB', 'Is a KFC UK Twister lower in calories than a Fillet Burger?', 'In the official portions compared here, no: the Fillet Burger lists463kcal, while the named Twisters range from482 to548kcal. The wrap’s sauce and full recipe matter.', body, rows, [source('KFC UK official nutrition and allergen table', rows[0]['source'], 'Official UK table with individual named recipes; sides and drinks are separate. No U.S. values or meal-bundle totals substituted.'), source('KFC UK Twister Wrap Meal', 'https://www.kfc.co.uk/our-menu/twisters/kfc-twister-wrap-meal', 'Confirms the meal presentation is distinct from a standalone named wrap.')], [{'label': 'Browse KFC UK', 'href': '/gb/en/restaurants/kfc/'}, {'label': 'Build your actual order', 'href': '/compare-complete-restaurant-orders.html?market=GB'}], ['kfc-healthy-meals-macros.html', 'burrito-wrap-cross-chain-no-size-standard.html'], 'UK chicken and named Twister sauce decision, with official local salt and missing-fibre handling; existing KFC guide is U.S.-focused.', 'KFC UK Twister wrap calories Fillet Burger protein'))

    # 5: Local sandwich build basis, not a generic protein ranking.
    rows = [get('GB', 'Subway', x) for x in ['Subs — Chicken Breast', 'Subs — Chicken Tikka', 'Subs — Rotisserie Style Chicken', 'Subs — Turkey', 'Subs — Tuna Mayo']]
    body = '''<h2>Compare the same six-inch basis</h2><p>Subway’s UK and Republic of Ireland September2026 table gives a six-inch sub basis that includes bread, the named protein and listed vegetables: onions, cucumber and lettuce. It does not provide a blanket total for every cheese, sauce and bread choice you could request.</p>''' + table(rows, 'Subway UK: the source’s six-inch sub builds', ('cal', 'p', 'c', 'fat', 'f', 'salt'), ['Chicken Breast', 'Chicken Tikka', 'Rotisserie Style Chicken', 'Turkey', 'Tuna Mayo']) + '''<h2>Which chicken build has more protein?</h2><p>Chicken Tikka lists 28 g protein and340? No: use the exact row—345 kcal. Chicken Breast is340kcal and26gprotein; Rotisserie Style Chicken is310kcal and22gprotein. Choosing Tikka over Chicken Breast changes this published build by5kcal and2gprotein.</p><p>The lower-calorie rotisserie sub is also the smaller source portion:177g, compared with197g for Tikka and198g for Chicken Breast. These are real order portions, not equal weights of cooked chicken.</p>''' + figure(rows[:3], ['Chicken Breast', 'Chicken Tikka', 'Rotisserie Style Chicken'], 'Protein in the published six-inch chicken builds', 'p') + '''<h2>Tuna is not the leanest filling by default</h2><p>The Tuna Mayo build lists400kcal,22gprotein and16gfat. That is the same listed protein as Rotisserie Style Chicken, with90more kcal and8.4gmore fat. This is a comparison of finished sandwich recipes, including the tuna recipe’s mayonnaise, not a judgment about plain tuna.</p><p>Turkey lists312kcal and22gprotein. Its1.8gsalt is higher than the rotisserie recipe’s1.4g, even though their calories and protein are close. Choose your priorities instead of expecting one ranking to answer every question.</p><h2>What if you add cheese or sauce?</h2><p>Keep the base build and each supported addition separate. Do not add a second chicken portion simply because the sub row includes chicken; that would double-count the default filling. A custom order without matching ingredient quantities should be labelled an estimate or left partly unknown.</p><h2>Use the right local menu</h2><p>These are UK-source six-inch builds, not U.S. Footlongs or Canadian recipes. The official UK nutrition page still links the September guide. The figures use that September edition and its stated build assumptions; they are not a promise that every customized local order has the same nutrition. Check the current local recipe when ordering.</p>''' + compare(rows[:3], 'Compare the three six-inch chicken builds')
    # Keep the editorial correction direct and clean in public copy.
    body = body.replace('28 g protein and340? No: use the exact row—345 kcal.', '28 g protein and345kcal.')
    output.append(article('subway-uk-six-inch-chicken-sandwich-nutrition', 'Subway UK six-inch chicken subs: compare the actual builds', 'Compare Subway UK Chicken Breast, Chicken Tikka and Rotisserie Style Chicken on the same published six-inch basis.', 'Eating out', 'GB', 'Which Subway UK six-inch chicken sub has more protein?', 'The September2026 UK builds list28gprotein for Chicken Tikka,26g for Chicken Breast and22g for Rotisserie Style Chicken, with different portion weights and recipes.', body, rows, [source('Subway UK official nutrition page', 'https://www.subway.com/en-gb/menunutrition/nutrition', 'Still links the September2026 UK/ROI guide during current official-page review.'), source('Subway UK/ROI September2026 nutrition guide', rows[0]['source'], 'September2026 UK/ROI edition. Bread, named protein and stated vegetables included; other customizations require their own supported amounts.', '2026-10-11')], [{'label': 'Browse the UK Subway selection', 'href': '/gb/en/restaurants/subway/'}, {'label': 'Keep country recipes separate', 'href': '/subway-turkey-breast-canada-vs-mexico.html'}], ['subway-healthy-meals-macros.html', 'subway-turkey-breast-canada-vs-mexico.html'], 'Three precise UK six-inch chicken builds and additions boundary; previous articles cover U.S. choices or a different Canada/Mexico turkey question.', 'Subway UK chicken tikka six inch calories protein'))

    # 6: Ramen broth and named menu variants.
    rows = [get('GB', 'Wagamama', x) for x in ['grilled chicken ramen', 'chilli chicken ramen', 'tantanmen beef brisket ramen', 'kare burosu ramen']]
    gf = get('GB', 'Wagamama', 'grilled chicken ramen · Gluten-free menu')
    body = '''<h2>Start with the named bowl, including its broth</h2><p>Wagamama’s standard grilled chicken ramen lists498kcal and35.7gprotein. Chilli chicken ramen lists589kcal and37.9gprotein. The latter adds91kcal and2.2gprotein in these published recipes; “chicken ramen” alone is not specific enough for an accurate log.</p>''' + table(rows, 'Wagamama UK standard-menu ramen: one whole named bowl', ('cal', 'p', 'c', 'fat', 'salt')) + '''<h2>Calories do not predict the salt ranking</h2><p>Grilled chicken has6.3gsalt in the source, chilli chicken7.7g, tantanmen beef brisket6.5g and kare burosu5.1g. The lowest-calorie bowl in this set does not have the lowest salt figure. These are recipe comparisons, not a score of which dish is healthier overall.</p><p>For a common sodium display,6.3gsalt corresponds to2,520mgsodium using salt grams ×1,000÷2.5. That is a salt-equivalent calculation. Wagamama separately reports 2.5 g sodium for this bowl, or 2,500 mg. Independently rounded salt and sodium need not convert to precisely the same number; the separately published sodium value is retained in the food record.</p>''' + figure(rows, ['Grilled chicken', 'Chilli chicken', 'Tantanmen beef', 'Kare burosu'], 'Salt in the four standard-menu ramen portions', 'salt') + '''<h2>Do you finish the broth?</h2><p>The restaurant supplies a whole-dish value, not a separate laboratory value for noodles, toppings and broth. Leaving broth can change what you consume, but we cannot calculate the exact salt reduction from these totals. Do not divide the bowl’s salt in half merely because half the broth remains: the ingredients do not necessarily contain salt evenly.</p><h2>The gluten-free-menu row is another build</h2><p>The separately listed grilled chicken ramen on the gluten-free menu is494kcal,28.4gprotein and2.5gsalt. Those values differ materially from the standard recipe. Select the corresponding row only when that is the dish ordered; do not quietly average the two or call the standard dish allergy-safe.</p>''' + table([rows[0], gf], 'Standard and separately listed gluten-free-menu grilled chicken ramen', ('cal', 'p', 'c', 'fat', 'salt'), ['Standard-menu recipe', 'Gluten-free-menu recipe']) + '''<h2>Log extras separately</h2><p>Extra noodles, egg, meat, sides or drinks change the meal. The table is one named bowl and no extra components. Northern Ireland has a separate menu link, so do not assume this main-menu snapshot establishes the recipe in every UK restaurant.</p>''' + compare(rows[:3], 'Compare the named ramen bowls')
    output.append(article('wagamama-uk-ramen-calories-protein-salt', 'Wagamama ramen: compare calories, protein and salt together', 'Compare four Wagamama UK ramen bowls, the separate gluten-free-menu recipe and the limits of subtracting uneaten broth.', 'Eating out', 'GB', 'How do Wagamama UK ramen bowls compare beyond calories?', 'The standard grilled chicken ramen lists498kcal,35.7gprotein and6.3gsalt. Chilli chicken ramen is589kcal,37.9gprotein and7.7gsalt; the full named recipe matters.', body, rows + [gf], [source('Wagamama official UK menu', rows[0]['source'], 'Current live menu and selected standard/gluten-free recipe nutrition inspected; snapshot values retained. Separate NorthernIreland menu is not treated as an equivalent recipe.')], [{'label': 'Browse Wagamama portions', 'href': '/gb/en/restaurants/wagamama/'}, {'label': 'Compare salt and sodium units', 'href': '/sodium-milligrams-to-grams.html'}], ['restaurant-bowl-nutrition-comparison.html', 'cross-chain-chicken-soup-no-sodium-assumption.html'], 'Ramen-specific broth logging, four local recipes and explicit standard/gluten-free distinction; not another broad bowl comparison.', 'Wagamama ramen calories protein salt grilled chicken'))

    # 7: Dressing basis and calculated per-portion macros.
    rows = [get('GB', 'Wasabi', x) for x in ['Harmony set', 'Harmony set (excl. dressing)', 'Mixed maki set', 'Mixed maki set (excl. dressing)', 'Rainbow set', 'Rainbow set (excl. dressing)']]
    body = '''<h2>Use the box total, not the per-100g energy column</h2><p>Wasabi’s guide supplies both calories per100g and calories per portion. Harmony is620kcal for its379g named portion; Mixed maki is433kcal for266g; Rainbow is554kcal for365g. Those values include the dressing in each named full version.</p>''' + table(rows, 'Wasabi UK sushi boxes: the published dressing variants', ('cal', 'p', 'c', 'fat', 'salt')) + '''<h2>The macro columns need the portion weight</h2><p>For Harmony, the source reports6.1gprotein per100g and a379gportion. GetMacros calculates6.1×379÷100=23.119gprotein, shown as23.1g here. Calories use the guide’s own620kcal per-portion value, not a re-created number from the separately rounded164kcalper100g.</p><p>The same method is used for carbohydrates, fat and salt. These calculated portion nutrients are not new lab measurements; rounding and hand-prepared portions limit their precision.</p>''' + figure([rows[0], rows[2], rows[4]], ['Harmony set', 'Mixed maki set', 'Rainbow set'], 'Energy in the full named sushi-box portions') + '''<h2>What does the dressing variant change?</h2><p>Harmony without dressing is609kcal,11kcalbelow the full version. Mixed maki without dressing is422kcal, also11kcalbelow, while Rainbow without dressing is542kcal,12kcalbelow. The source provides the separate versions; choose the one you ate.</p><p>The salt difference is more noticeable than the calorie difference. Harmony’s full portion calculates to about4.74gsalt; its367gwithout-dressing version calculates to about3.12g. Treat these as rounded source-derived totals, not exact sauce-package measurements.</p><h2>Do not count the dressing twice</h2><p>Logging the full Harmony set and then adding a dressing entry counts the included dressing again. Conversely, choosing the no-dressing row while eating the dressing understates the order. Extra soy sauce is another component and is not automatically covered by every box name.</p><h2>A smaller box is not an equal serving</h2><p>Mixed maki weighs less than Harmony or Rainbow. Compare the complete box for an order decision; use an equal-weight basis only when that answers your question. Sushi-piece size and fillings vary, so “eight pieces” from an independent restaurant cannot inherit these chain-specific numbers.</p>''' + compare([rows[0], rows[2], rows[4]], 'Compare the three whole sushi boxes')
    output.append(article('wasabi-sushi-set-dressing-nutrition', 'Wasabi sushi boxes: Harmony, Mixed maki and Rainbow compared', 'Compare three Wasabi UK sushi boxes, their dressing variants and the correct per-portion calculation for macros.', 'Meal comparisons', 'GB', 'Do Wasabi sushi-set calories include dressing, and how do the boxes compare?', 'The full Harmony, Mixed maki and Rainbow set rows list620, 433 and 554kcal respectively. Separate no-dressing rows exist, so match that exact version instead of adding dressing twice.', body, rows, [source('Wasabi UK nutrition guide · Version34, released17September2026', rows[0]['source'], 'Per-portion calories reported by Wasabi; protein, carbs, fat and salt calculated from per100g × named portion weight. Version34 released17September2026.')], [{'label': 'Browse Wasabi UK portions', 'href': '/gb/en/restaurants/wasabi/'}, {'label': 'Review a food portion', 'href': '/food-diary.html?market=GB'}], ['el-pollo-loco-salad-dressing-boundary.html', 'serving-size-vs-portion-size.html'], 'Distinct chain-specific sushi-set calculations, portion weights and supplied without-dressing variants; no existing Wasabi article.', 'Wasabi sushi calories Harmony Rainbow mixed maki dressing'))

    # 8: Whole pizzas, not invented chain-universal slices.
    rows = [get('GB', 'PizzaExpress', x) for x in ['Classic — Margherita', 'Romana — Margherita', 'Large Classic — Margherita', 'Classic — Margherita GF', 'Romana — Margherita GF']]
    body = '''<h2>Classic and Romana are whole-pizza entries</h2><p>PizzaExpress lists the Classic Margherita at711kcal and35.1gprotein, and Romana Margherita at769kcal and40gprotein. The complete Romana is58kcalhigher, with4.9gmoreprotein. A thinner-looking base does not establish fewer calories in the entire served pizza.</p>''' + table(rows, 'PizzaExpress UK Margherita: one whole named pizza', ('cal', 'p', 'c', 'fat', 'salt'), ['Classic', 'Romana', 'Large Classic', 'Classic gluten-free', 'Romana gluten-free']) + '''<h2>A slice is the fraction you actually eat</h2><p>If a Classic is cut into six equal shares, one share is711÷6=118.5kcal. If the same pizza is cut into eight equal shares, one is88.9kcal after rounding. Cutting changes the slice number, not the energy in the pizza.</p><p>For half the Classic, use355.5kcal and17.55gprotein before display rounding. Half the Romana is384.5kcal and20gprotein. These are equal-fraction estimates from a whole-pizza total; toppings may not be distributed perfectly.</p>''' + figure(rows[:3], ['Classic whole pizza', 'Romana whole pizza', 'Large Classic whole pizza'], 'Same pizza name, different whole-pizza portions') + '''<h2>Large Classic is not the regular Classic entry</h2><p>The Large Classic Margherita lists1,347kcal and69.2gprotein. That is636kcalmore than the regular Classic. Do not use the smaller entry for a larger takeaway pizza just because both names contain Margherita.</p><h2>Gluten-free versions are separate recipes</h2><p>The Classic gluten-free version lists685kcal, while the Romana gluten-free version lists1,033kcal. The direction and size of the difference do not follow a simple rule that gluten-free means fewer calories. Protein also changes:22.9g and31.2g respectively.</p><p>These labels identify source menu recipes. They do not establish that a preparation environment is safe for an allergy or coeliac disease; consult the restaurant’s current information.</p><h2>Build the rest of the meal separately</h2><p>The comparison excludes starters, garlic butter, extra toppings, drinks and dessert. A side of dough balls is not hidden in the pizza row. Check dine-in versus takeaway and the exact format before selecting a record, then log the portion of that named pizza you ate.</p>''' + compare(rows[:3], 'Compare the three whole-pizza formats')
    output.append(article('pizzaexpress-classic-romana-margherita-nutrition', 'PizzaExpress Margherita: Classic, Romana or Large Classic?', 'Compare whole PizzaExpress UK Margherita portions, calculate a slice correctly and keep gluten-free builds separate.', 'Meal comparisons', 'GB', 'Does a PizzaExpress Romana Margherita have fewer calories than Classic?', 'The whole Romana Margherita lists769kcal versus711kcal for Classic in this source. Slice counts, large formats and gluten-free builds need their own matching basis.', body, rows, [source('PizzaExpress official UK nutrition table', rows[0]['source'], 'Official UK whole-pizza portions; no universal slice size or cross-country equivalent assumed.'), source('PizzaExpress official restaurant menu', 'https://mobile-pay.pizzaexpress.com/our-restaurant-menu/mains', 'Confirms the current Classic Margherita menu entry; local configuration and availability can vary.')], [{'label': 'Browse PizzaExpress UK', 'href': '/gb/en/restaurants/pizzaexpress/'}, {'label': 'Compare a chosen fraction', 'href': '/compare-foods.html?market=GB'}], ['canada-pepperoni-pizza-three-slice-comparison.html', 'restaurant-menu-serving-weight.html'], 'UK whole-pizza formats, concrete equal-fraction example and actual gluten-free recipes; no existing PizzaExpress comparison.', 'PizzaExpress Classic Romana Margherita calories'))

    # 9: Supported ingredient allocations; do not assume bowl = burrito minus wrap.
    names = ['Tortilla Wrap', 'Coriander Rice (Burrito)', 'Coriander Rice (Bowl)', 'Black Beans', 'Chicken Asado', 'Pico de Gallo', 'Guacamole']
    rows = [get('GB', 'Tortilla', 'Medium Burrito/Bowl — ' + name) for name in names]
    wrap, rice_burrito, rice_bowl, beans, chicken, pico, guac = rows
    burrito = add('Medium chicken burrito, selected build', [wrap, rice_burrito, beans, chicken, pico], 'wrap + burrito rice + black beans + chicken + pico')
    bowl = add('Medium chicken bowl, selected build', [rice_bowl, beans, chicken, pico], 'bowl rice + black beans + chicken + pico; no wrap')
    body = '''<h2>The rice portion changes with the format</h2><p>Tortilla’s medium guide allocates117kcal of coriander rice to a burrito, but175kcal to a bowl. The medium wrap itself is195kcal. A bowl is therefore not this burrito minus195kcal: it uses a different rice allocation.</p>''' + table(rows, 'Tortilla UK medium-build ingredients: one named allocation each', ('cal', 'p', 'c', 'fat', 'f'), names) + '''<h2>Build the same chosen fillings deliberately</h2><p>For a medium burrito with coriander rice, black beans, Chicken Asado and pico de gallo, the source allocations total195+117+79+133+12=536kcal and34gprotein. Using the bowl rice allocation and no wrap gives175+79+133+12=399kcal and30gprotein.</p><p>The difference is137kcal, not195. Both calculations include the selected rice, beans, chicken and salsa once. Neither includes cheese, sour cream, guacamole or other additions.</p>''' + table([burrito, bowl], 'Calculated medium orders with the explicitly named components') + figure([burrito, bowl], ['Selected medium burrito', 'Selected medium bowl'], 'A format change includes the corresponding rice allocation') + '''<h2>Guacamole is a separate supported addition</h2><p>The medium guide lists95kcal and1gprotein for guacamole. Adding that one allocation to the selected bowl makes494kcal and31gprotein. Use its own row instead of assuming every burrito or bowl includes it.</p><h2>Stay inside the medium column</h2><p>The source has separate large, salad, taco and other sections. Large chicken or rice allocations should not be mixed into a medium build without saying so. “Double chicken” also needs the actual serving rule; it is not a license to double the entire finished order.</p><h2>How to read the limits</h2><p>These are GetMacros sums of the restaurant’s published ingredient allocations. They are not a restaurant-published finished meal or a measured individual scoop. Tortilla states that portions are served by hand and can vary.</p><p>The worked example retains the named kcal and macro fields. It does not recalculate energy from the guide’s kJ entries or guess corrections to source discrepancies. Ingredient preferences do not replace the restaurant’s allergen advice.</p>'''
    output.append(article('tortilla-uk-burrito-bowl-rice-portions', 'Tortilla UK: a bowl is more than a burrito without the wrap', 'Calculate a defined medium chicken burrito and bowl using Tortilla’s different rice allocations, then add supported extras.', 'Meal comparisons', 'GB', 'How many calories change when a medium Tortilla burrito becomes a bowl?', 'For the selected chicken, black-bean and pico build, the calculated burrito is536kcal and the bowl399kcal. The bowl has more allocated rice, so simply subtracting the195kcal wrap is incorrect.', body, rows, [source('Tortilla UK nutrition and allergen guide · updated17September2026', rows[0]['source'], 'Guide updated17September2026, page4 medium ingredient allocations. Totals are GetMacros calculations, not restaurant-published finished orders.'), source('Tortilla official UK menu', 'https://www.tortilla.co.uk/menu', 'Confirms format and configurable ingredient context, without claiming a complete default build.')], [{'label': 'Browse Tortilla ingredient allocations', 'href': '/gb/en/restaurants/tortilla/'}, {'label': 'Compare complete orders', 'href': '/compare-complete-restaurant-orders.html?market=GB'}], ['qdoba-burrito-bowl-published-pair.html', 'chipotle-rice-beans-nutrition.html'], 'Tortilla-specific medium rice allocation changes, explicit compositional arithmetic and optional guacamole; neither QDOBA nor Chipotle portions reused.', 'Tortilla UK burrito bowl calories rice nutrition'))

    # 10: One useful milk/size article rather than one page per milk.
    names = ['Latte · Semi Skimmed Milk · Regular', 'Latte · Skimmed Milk · Regular', 'Latte · Whole Milk · Regular', 'Latte · Soya · Regular', 'Latte · Oat · Regular', 'Latte · Almond · Regular']
    rows = [get('GB', 'Caffè Nero', x) for x in names]
    grande = get('GB', 'Caffè Nero', 'Latte · Semi Skimmed Milk · Grande')
    body = '''<h2>Milk choice changes more than calories</h2><p>A regular Caffè Nero latte with semi-skimmed milk lists123kcal and9.1gprotein. Skimmed milk lists99kcal with the same protein. Whole milk lists165kcal and8.9gprotein. Compare the finished drink recipe instead of applying a generic milk-swap estimate.</p>''' + table(rows, 'Caffè Nero UK: regular hot Latte with each named milk or drink', ('cal', 'p', 'c', 'fat', 'sugar'), ['Semi-skimmed', 'Skimmed', 'Whole', 'Soya', 'Oat', 'Almond']) + '''<h2>Plant drinks are not interchangeable</h2><p>The regular soya latte is115kcal and8.9gprotein. The oat version is155kcal and3gprotein, while almond is75kcal and2.3gprotein. If protein matters to you, the smallest calorie figure does not also give the most protein.</p><p>These numbers describe Caffè Nero’s named UK recipes. They do not establish the nutrient content of every carton sold as oat, almond or soya drink, and they do not verify fortification or allergy safety.</p>''' + figure([rows[0], rows[3], rows[4], rows[5]], ['Semi-skimmed', 'Soya', 'Oat', 'Almond'], 'Protein in one regular hot Latte', 'p') + '''<h2>Regular and Grande need their own entries</h2><p>With semi-skimmed milk, Grande lists183kcal and13.1gprotein. Compared with regular, that adds60kcal and4gprotein. It is not a simple doubling: twice123kcal would be246kcal, which is not the published Grande value.</p>''' + table([rows[0], grande], 'Same milk choice, two actual hot-drink sizes', ('cal', 'p', 'c', 'fat', 'sugar'), ['Regular semi-skimmed', 'Grande semi-skimmed']) + '''<h2>Hot, iced and flavoured drinks are separate builds</h2><p>This table is the hot Latte, not an Iced Latte, a Cinnamon Roll Latte or a drink with extra syrup. Ice, milk allocation and included flavouring can change the recipe. Select the exact item when logging rather than changing only the display name.</p><h2>Total sugars are not added sugars</h2><p>The source’s sugars field is total sugars. Milk naturally contributes lactose; this table does not identify how much added sugar is present in each recipe. Do not subtract all sugar when asking for no extra syrup, or call a drink sugar-free because no spoonful was added.</p><p>For a repeat order, save the exact size and milk choice. A future recipe update should not silently replace the nutrition snapshot of a drink already logged.</p>''' + compare([rows[0], rows[3], rows[4]], 'Compare semi-skimmed, soya and oat regular Lattes')
    output.append(article('caffe-nero-latte-milk-size-nutrition', 'Caffè Nero Latte: compare milk choices and sizes', 'Compare Caffè Nero UK regular Lattes by milk, protein, calories and total sugars, then see what changes with Grande.', 'Coffee & drinks', 'GB', 'Which milk choice changes a Caffè Nero Latte’s calories and protein?', 'For a regular UK Latte, semi-skimmed lists123kcal and9.1gprotein, soya115kcal and8.9g, oat155kcal and3g, and almond75kcal and2.3g. Size and recipe must also match.', body, rows + [grande], [source('Caffè Nero UK official coffee menu', rows[0]['source'], 'Official UK hot Latte recipes with named milk/drink and size. Total sugars are not an added-sugar breakdown.')], [{'label': 'Browse Caffè Nero UK', 'href': '/gb/en/restaurants/caffe-nero/'}, {'label': 'Compare two drink recipes', 'href': '/compare-foods.html?market=GB'}], ['tim-hortons-canada-protein-latte-vs-latte.html', 'starbucks-healthy-food-meals-macros.html'], 'Specific UK Caffè Nero regular/Grande milk builds, not Tim Hortons protein milk or a general plant-beverage guide.', 'Caffe Nero latte calories oat milk protein regular grande'))

    # 11: Whole burger rows retained even when ingredient sums differ.
    rows = [get('GB', 'Five Guys', x) for x in ['Little Hamburger', 'Hamburger', 'Little Cheeseburger', 'Cheeseburger']]
    mini = get('GB', 'Five Guys', 'Mini Fries')
    little_fries = get('GB', 'Five Guys', 'Little Fries')
    totals = [add('Little Hamburger + Mini Fries', [rows[0], mini], '1 named burger + 1 Mini Fries'), add('Little Hamburger + Little Fries', [rows[0], little_fries], '1 named burger + 1 Little Fries')]
    body = '''<h2>“Little” describes the burger build</h2><p>The official UK ordering menu identifies one beef patty in the Little Hamburger and two in the Hamburger. Their published finished-order nutrition is464kcal and24gprotein for Little, versus678kcal and42gprotein for Hamburger.</p>''' + table(rows, 'Five Guys UK: the published whole burger portions', ('cal', 'p', 'c', 'fat', 'salt')) + '''<h2>Use the whole row, not a guessed patty subtraction</h2><p>The named burgers differ by214kcal and18gprotein in the source. That is the comparison to use for these finished orders. The guide also contains separate ingredient entries, but adding or subtracting them may not reproduce the independently rounded whole-burger rows. Do not “correct” the restaurant’s total by silently rebuilding it.</p><p>Little Cheeseburger is512kcal and27gprotein; Cheeseburger is811kcal and50gprotein. The difference between the cheese versions is299kcal, so you cannot apply one universal “Little” calorie reduction to every burger name.</p>''' + figure(rows, ['Little Hamburger', 'Hamburger', 'Little Cheeseburger', 'Cheeseburger'], 'Calories in four named UK burger builds') + '''<h2>The fries choice can outweigh the burger change</h2><p>Mini Fries list350kcal and5gprotein; Little Fries list659kcal and10gprotein. With the same Little Hamburger, those selected food totals are814kcal and29gprotein, or1,123kcal and34gprotein.</p>''' + table(totals, 'Calculated Little Hamburger and fries orders; no drink or extra toppings') + '''<p>The309kcal difference between these fries portions is larger than the214kcal difference between the Little Hamburger and Hamburger. That is why looking only at the burger can miss a bigger change in your actual order.</p><h2>What toppings are included?</h2><p>These calculations retain the whole named burger row and do not add optional toppings. A requested sauce, cheese change or extra bacon needs its own supported entry and serving. Free toppings are not necessarily zero in nutrition.</p><h2>Keep the UK guide attached</h2><p>The source is the official UK guide dated13October2026. It does not establish U.S. or Canadian formulations, local prices, or exact bag weights on a particular visit. If you share fries, use the fraction actually eaten as an estimate; the named portion is not proof of each person’s share.</p>''' + compare(rows[:3], 'Compare the named burger portions')
    output.append(article('five-guys-uk-little-hamburger-cheeseburger', 'Five Guys UK: Little or regular burger—and which fries?', 'Compare UK Little and regular Hamburgers and Cheeseburgers, then calculate two actual burger-and-fries orders.', 'Eating out', 'GB', 'How much changes between a Five Guys UK Little burger and regular burger?', 'Little Hamburger lists464kcal and24gprotein; Hamburger lists678kcal and42g. The fries portion is a separate decision: Mini and Little Fries differ by309kcal.', body, rows + [mini, little_fries], [source('Five Guys UK nutrition guide ·13October2026', rows[0]['source'], '13October2026 UK guide. Whole burger totals used instead of recomposing independently rounded ingredient entries.'), source('Five Guys UK official ordering menu', 'https://order.fiveguys.co.uk/menu', 'Confirms one versus two patties and listed burger calorie figures. Prices observed are not used as nationwide prices.')], [{'label': 'Browse Five Guys UK', 'href': '/gb/en/restaurants/five-guys/'}, {'label': 'Save an exact order', 'href': '/food-shelf.html'}], ['in-n-out-double-vs-two-hamburgers.html', 'burger-variants-not-nine-base-burgers.html'], 'Actual UK Five Guys serving names and fries combinations; existing In-N-Out comparisons are another restaurant and ordering question.', 'Five Guys UK Little Hamburger Cheeseburger calories fries'))

    # 12: Two compatible topping allocations, plus a base swap.
    rows = [get('GB', 'Chopstix', x) for x in ['VEGETABLE CHOW MEIN · Regular', 'EGG FRIED RICE · Regular', 'CAULI RICE · Regular', 'CARAMEL DRIZZLE CHICKEN · R/L/XL', 'SWEET & SOUR CHICKEN · R/L/XL']]
    noodles, rice, cauli, caramel, sweet = rows
    totals = [add('Regular noodles + Caramel + Sweet & Sour', [noodles, caramel, sweet], '1 Regular base + 1 R/L/XL allocation of each named topping'), add('Regular egg fried rice + Caramel + Sweet & Sour', [rice, caramel, sweet], '1 Regular base + 1 R/L/XL allocation of each named topping'), add('Regular cauli rice + Caramel + Sweet & Sour', [cauli, caramel, sweet], '1 Regular base + 1 R/L/XL allocation of each named topping')]
    body = '''<h2>The base is not the finished box</h2><p>Chopstix explicitly instructs customers to add selected toppings to the base’s nutrition. Its Regular Vegetable Chow Mein is308kcal; that does not include the chicken toppings in this worked example.</p>''' + table(rows, 'Chopstix UK: compatible named base and topping allocations', ('cal', 'p', 'c', 'fat', 'salt'), ['Regular Vegetable Chow Mein', 'Regular Egg Fried Rice', 'Regular Cauli Rice', 'Caramel Drizzle Chicken · R/L/XL', 'Sweet & Sour Chicken · R/L/XL']) + '''<h2>Build one explicit two-topping example</h2><p>Regular noodles plus one R/L/XL Caramel Drizzle allocation and one R/L/XL Sweet & Sour allocation totals308+169+162=639kcal. Protein totals9.3+10.5+9.7=29.5g. The sauces belonging to the named chicken recipes are already inside those topping rows.</p><p>This is our component calculation, not a universal calorie label for every Regular box. An extra dip, another topping, a changed allocation or a different base needs its own row.</p>''' + table(totals, 'Calculated orders: same two toppings, three Regular bases', ('cal', 'p', 'c', 'fat', 'salt')) + figure(totals, ['Noodle-base order', 'Egg-fried-rice order', 'Cauli-rice order'], 'Base choice with the same two topping allocations') + '''<h2>The base change is measurable</h2><p>Using Regular Egg Fried Rice instead gives796kcal and28.2gprotein. Regular Cauli Rice gives389kcal and23.7gprotein. Those are differences for named portions, not equal weights of rice, noodles and vegetables.</p><p>The noodle-based example totals5.08gsalt; egg fried rice3.71g; cauli rice4.51g. A change can affect calories, protein and salt differently. No overall health ranking follows from one column.</p><h2>Small and Topper are not the R/L/XL amount</h2><p>Caramel Drizzle Chicken has separate Small, R/L/XL and Topper columns. Small lists253kcal and Topper327kcal, compared with169kcal for R/L/XL. Choosing the wrong column can substantially misstate the box.</p><h2>What if you cannot identify the allocation?</h2><p>Keep the portion uncertain rather than substituting an arbitrary gram weight. The public columns name allocations without supplying reliable gram weights for these rows. Match the source’s size and restaurant serving rule, check with staff if needed, and log extra dips separately.</p>'''
    output.append(article('chopstix-uk-box-base-toppings-calories', 'Chopstix UK calories: build the base and toppings together', 'Calculate noodles, egg fried rice or cauli rice with the same two Chopstix chicken topping allocations.', 'Meal comparisons', 'GB', 'How do I calculate the calories in a Chopstix box?', 'Add the named base and each matching topping allocation. Regular Vegetable Chow Mein with the selected R/L/XL Caramel Drizzle and Sweet & Sour Chicken allocations totals639kcal and29.5gprotein.', body, rows + [get('GB', 'Chopstix', 'CARAMEL DRIZZLE CHICKEN · Small'), get('GB', 'Chopstix', 'CARAMEL DRIZZLE CHICKEN · Topper')], [source('Chopstix Vegetable Chow Mein official nutrition table', noodles['source'], 'Current Regular base values and explicit instruction to add topping nutrition rechecked.'), source('Chopstix Caramel Drizzle Chicken official table', caramel['source'], 'R/L/XL column distinguished from Small and Topper; current values rechecked.'), source('Chopstix Sweet & Sour Chicken official table', sweet['source'], 'Named matching allocation, not a standalone full box.'), source('Chopstix Egg Fried Rice official table', rice['source'], 'Regular base only.'), source('Chopstix Cauli Rice official table', cauli['source'], 'Regular base only.')], [{'label': 'Browse Chopstix portions', 'href': '/gb/en/restaurants/chopstix/'}, {'label': 'Use the complete-order builder', 'href': '/compare-complete-restaurant-orders.html?market=GB'}], ['panda-express-base-nutrition-comparison.html', 'calculate-macros-mixed-bowl.html'], 'UK Chopstix specific size-column rules, two matching toppings and computed alternative bases; other chain values never substituted.', 'Chopstix calories regular box noodles toppings'))

    # 13: Seasonal drink exact build, not a guessed customization calculator.
    rows = [get('GB', 'Starbucks', x) for x in ['Pumpkin Spice Latte - skimmed milk · Tall', 'Pumpkin Spice Latte - skimmed milk · Grande', 'Iced Pumpkin Spice Latte - skimmed milk · Tall', 'Iced Pumpkin Spice Latte - skimmed milk · Grande']]
    body = '''<h2>Match country, milk, temperature and size</h2><p>Starbucks’ Autumn2026 UK guide lists the skimmed-milk Tall Pumpkin Spice Latte at185kcal and its iced counterpart at119kcal. The Grande versions list231kcal hot and167kcal iced. These are four published builds, not one drink with ice mathematically subtracted.</p>''' + table(rows, 'Starbucks UK Autumn2026: named skimmed-milk Pumpkin Spice Latte builds', ('cal', 'p', 'c', 'fat', 'sugar'), ['Tall hot', 'Grande hot', 'Tall iced', 'Grande iced']) + '''<h2>Why the iced version is not just colder</h2><p>The UK guide’s hot skimmed-milk ingredient list includes whipped topping; the selected iced skimmed-milk list does not. Ice and the rest of the build also differ. Therefore the66kcalTall difference or64kcalGrande difference cannot be presented as a measured “remove whipped cream” value.</p><p>Removing an ingredient or ordering fewer pumps requires published component amounts or a supported customized recipe. This table does not guess those effects.</p>''' + figure(rows, ['Tall hot', 'Grande hot', 'Tall iced', 'Grande iced'], 'Energy in the four published skimmed-milk builds') + '''<h2>Size changes protein as well</h2><p>The hot versions list6.7gprotein for Tall and9.1g for Grande; the iced versions list5.1g and7.7g. A larger drink increases protein here because it is another full recipe, but it also changes calories and other nutrients. It is not automatically a useful way to meet a protein target.</p><h2>Total sugars are not an added-sugar measurement</h2><p>The iced Grande lists28.8gtotal sugars. That includes the recipe’s total, not an independently reported added-sugars breakdown. Skimmed milk does not make a flavoured latte sugar-free. Equally, the full sugar value cannot be treated as the amount removed by asking for less sauce.</p><h2>UK recipes stay separate from U.S. recipes</h2><p>The source is the UK Autumn2026 guide dated18September. Cup names alone do not establish an equivalent formulation in another country, and millilitre volumes are not supplied for these selected table rows.</p><p>For logging, save all four identifying details: UK, hot or iced, named size and skimmed milk. This seasonal source does not promise that every branch has the product in stock, or that the recipe will stay the same after the seasonal menu changes.</p>''' + compare([rows[1], rows[3]], 'Compare the two Grande builds')
    output.append(article('starbucks-uk-pumpkin-spice-latte-hot-iced', 'Starbucks UK Pumpkin Spice Latte: hot or iced, Tall or Grande?', 'Compare four exact UK skimmed-milk Pumpkin Spice Latte builds without guessing syrup or whipped-cream customizations.', 'Coffee & drinks', 'GB', 'How do hot and iced Pumpkin Spice Lattes compare in the UK?', 'For the skimmed-milk UK recipes, Tall is185kcalhot or119kcaliced; Grande is231kcalhot or167kcaliced. They are different full builds, including different topping assumptions.', body, rows, [source('Starbucks UK Autumn2026 beverage nutrition and ingredients guide', rows[0]['source'], 'UK Autumn2026 guide dated18September. Exact hot/iced skimmed-milk recipes, sizes and included topping descriptions retained.'), source('Starbucks UK official nutrition and allergen guidance', 'https://www.starbucks.co.uk/nutrition-allergens', 'Local recipe and allergy information, not U.S. substitution values.')], [{'label': 'Browse Starbucks UK drinks', 'href': '/gb/en/restaurants/starbucks/'}, {'label': 'Compare country recipes', 'href': '/compare-menu-ingredients-worldwide.html'}], ['starbucks-healthy-food-meals-macros.html', 'tim-hortons-canada-protein-latte-vs-latte.html'], 'Precise UK seasonal hot/iced recipe comparison, with real ingredient-list distinction, not an existing food or Canadian protein-drink guide.', 'Starbucks UK Pumpkin Spice Latte calories iced skimmed Tall Grande'))

    # 14: Adult lunch recipes, not the kids rice-box row.
    rows = [get('GB', 'LEON', x) for x in ['Chicken Aioli Wrap', 'Aioli Chicken Big Box', 'Spicy Chicken Zhoug Wrap', 'Satay Chicken Big Box']]
    body = '''<h2>The Aioli wrap and Big Box are different lunches</h2><p>LEON’s Chicken Aioli Wrap is266g,566kcal and27gprotein. The Aioli Chicken Big Box is481g,770kcal and29gprotein. The box adds204kcal and2gprotein, while supplying a much larger total food portion.</p>''' + table(rows, 'LEON UK: adult lunch portions, as published', ('cal', 'p', 'c', 'fat', 'f', 'salt')) + '''<h2>Look beyond the word “chicken”</h2><p>The wrap combines chicken with khobez bread, aioli and salad ingredients. The Big Box is a rice-based recipe with slaw, seeds and aioli. It is not the same wrap with bread removed, nor does the2gprotein difference measure the amount of extra chicken.</p><p>The complete source weights differ by215g. Much of a larger meal can come from ingredients other than its named protein. Use the full nutrition table rather than assuming a larger box has proportionally more protein.</p>''' + figure(rows, ['Chicken Aioli Wrap', 'Aioli Chicken Big Box', 'Spicy Chicken Zhoug Wrap', 'Satay Chicken Big Box'], 'Protein across the four adult chicken lunch recipes', 'p') + '''<h2>A spicy wrap offers another distinct recipe</h2><p>The Spicy Chicken Zhoug Wrap lists479kcal,29gprotein and4gfibre. It has the same listed protein as the Aioli Chicken Big Box, with291fewer kcal in its263gportion. That does not make it the same amount of food or guarantee the same fullness.</p><p>The Satay Chicken Big Box lists776kcal and32gprotein for507g. Its source ingredients include peanut satay sauce and fish sauce. A different sauce can change ingredients and allergy considerations even when the calories are close to another box.</p><h2>Fibre and salt answer different questions</h2><p>The Aioli wrap has2.7gfibre and1.45gsalt; the Aioli Big Box has5.8gfibre and2.65gsalt. The larger recipe adds fibre and also more salt. Those trade-offs are more informative than calling every rice box a better choice than every wrap.</p><h2>Choose the exact entry</h2><p>LEON also lists a Chargrilled Chicken Rice Box aimed at children. It is not the adult Aioli Big Box and is deliberately excluded here. Check the recipe and portion name, then add any extra side, drink or sauce separately. The figures are whole named recipes, not a customization calculator.</p>''' + compare(rows[:3], 'Compare the adult lunch recipes')
    output.append(article('leon-uk-chicken-wrap-rice-box-nutrition', 'LEON UK chicken lunch: wrap or Big Box?', 'Compare adult LEON UK chicken wraps and rice-based Big Boxes by portion, protein, calories, fibre and salt.', 'Eating out', 'GB', 'Does a LEON UK chicken Big Box contain much more protein than a wrap?', 'The Aioli Chicken Big Box lists29gprotein versus27g in the Chicken Aioli Wrap, with770versus566kcal and481versus266g total food. Format and full recipe matter.', body, rows, [source('LEON Chicken Aioli Wrap official product page', rows[0]['productUrl'], 'Current portion weight, calories, protein and ingredient context independently re-read.'), source('LEON Aioli Chicken Big Box official product page', rows[1]['productUrl'], 'Current adult rice-based recipe,481g,770kcal,29gprotein independently re-read.'), source('LEON Spicy Chicken Zhoug Wrap', rows[2]['productUrl'], 'Named adult wrap values independently checked.'), source('LEON Satay Chicken Big Box', rows[3]['productUrl'], 'Named adult rice-based recipe values and peanut/fish ingredient distinction checked.')], [{'label': 'Browse LEON UK', 'href': '/gb/en/restaurants/leon/'}, {'label': 'Compare LEON breakfast separately', 'href': '/leon-uk-breakfast-muffin-egg-pot-nutrition.html'}], ['leon-uk-breakfast-muffin-egg-pot-nutrition.html', 'protein-sort-vs-portion-mass.html'], 'Adult lunch recipe decision using four official product pages, separate from existing breakfast formats and general portion-weight arithmetic.', 'LEON chicken aioli wrap big box calories protein'))

    # 15: One main fixed; side size and default coffee fully specified.
    bacon = get('US', 'Burger King', "Bacon, Egg, & Cheese Croissan'wich")
    sausage = get('US', 'Burger King', "Sausage, Egg, & Cheese Croissan'wich")
    sides = [get('US', 'Burger King', x) for x in ['Small Hash Browns', 'Medium Hash Browns', 'Large Hash Browns']]
    coffee = get('US', 'Burger King', 'Small Brewed Coffee')
    totals = [add("Bacon, Egg & Cheese Croissan’wich + " + side['name'] + ' + small black coffee', [bacon, side, coffee], '1 named sandwich + named hash-brown size + small brewed coffee') for side in sides]
    body = '''<h2>Fix the sandwich, then compare the side</h2><p>The U.S. nutrition explorer lists the Bacon, Egg & Cheese Croissan’wich at360kcal and15gprotein. Small Hash Browns add270kcal; Medium add510kcal; Large add700kcal. Those are three side servings, not a handful-size estimate.</p>''' + table([bacon, sausage] + sides + [coffee], 'Burger King U.S.: individual breakfast components', ('cal', 'p', 'c', 'fat', 'na')) + '''<h2>Three breakfasts with the same main and coffee</h2><p>With a small brewed coffee as listed and no additions, the selected bacon breakfast totals630kcal with Small Hash Browns,870kcal with Medium, or1,060kcal with Large. Protein totals17g,19g and21g respectively.</p>''' + table(totals, 'GetMacros-calculated breakfasts; coffee has no cream or sugar') + figure(totals, ['Bacon sandwich + Small side', 'Bacon sandwich + Medium side', 'Bacon sandwich + Large side'], 'Hash-brown size changes the selected breakfast total') + '''<h2>The side change can be bigger than the sandwich change</h2><p>Switching the bacon sandwich to the Sausage, Egg & Cheese Croissan’wich changes the main from360to500kcal, adding140kcal and4gprotein. Keeping the bacon main but moving Small Hash Browns to Medium adds240kcal and2gprotein.</p><p>That comparison identifies two separate ordering decisions. It does not tell you which breakfast you should eat or turn higher calories into a moral judgment.</p><h2>Why an old PDF may disagree</h2><p>Older official PDFs still appear in search results with different Croissan’wich and hash-brown figures. This article uses the current U.S. nutrition-explorer snapshot reviewed in October2026, not a mixture of values from several editions. An old source being hosted on an official domain does not make it the current menu.</p><h2>Know what is included</h2><p>The named sandwich’s egg, cheese and meat belong to its finished recipe. Do not add their full values again. The coffee entry is brewed coffee without assumed cream or sugar; flavoured or “plain” iced coffee can be a different sweetened recipe with its own row.</p><p>These are calculated combinations, not a promise that a local restaurant sells them as a particular combo or price. No sauce, extra sandwich, modified filling or other drink is included. Source gram weights lack a verified display unit here, so no gram-based serving conversion is invented.</p>''' + compare(sides, 'Compare the three U.S. hash-brown sizes')
    output.append(article('burger-king-us-breakfast-hash-browns-order', 'Burger King U.S. breakfast: count the hash-brown size', 'Calculate a Bacon, Egg & Cheese Croissan’wich breakfast with Small, Medium or Large Hash Browns using current U.S. source portions.', 'Breakfast', 'US', 'How much do hash browns add to a Burger King U.S. breakfast?', 'The Bacon, Egg & Cheese Croissan’wich with Small Hash Browns and small black brewed coffee totals630kcal and17gprotein. Medium Hash Browns make870kcal; Large make1,060kcal.', body, [bacon, sausage] + sides + [coffee], [source('Burger King U.S. official nutrition explorer', bacon['source'], 'Current official page independently confirms named calorie figures. Full macro rows retain the reviewed17October2026 prod_bk_us source snapshot; no old PDF values mixed in.')], [{'label': 'Browse Burger King U.S.', 'href': '/burger-king-healthy-meals-macros.html'}, {'label': 'Find a U.S. breakfast', 'href': '/restaurant-meal-finder.html?market=US&meal=breakfast'}], ['burger-king-us-whopper-cheese-standard-serving.html', 'breakfast-food-vs-combo-menu.html'], 'Specific current U.S. breakfast component totals and size decision, distinct from the burger guide and generic item-versus-combo methodology.', 'Burger King breakfast calories Croissan wich hash browns small medium'))
    assert len(output) == 15
