ARTICLES = articles()


def export():
    OUT.mkdir(parents=True, exist_ok=True)
    manifest = {'preparedAt': DATE, 'status': '15 authored articles; not counted as live until release deployment verification', 'newRestaurantRecords': 0, 'existingSourceServingsUsed': len(USED), 'articles': ARTICLES, 'evidence': list(USED.values()), 'replacedCandidates': [{'candidate': 'Tim Hortons Double Double by size', 'disposition': 'Not authored: current selected evidence only supports medium; no size extrapolation.'}, {'candidate': 'A&W Canada breakfast comparison', 'disposition': 'Not authored: source calorie/macro inconsistencies need dedicated review.'}, {'candidate': 'Culver’s burger protein comparison', 'disposition': 'Replaced: different official source editions expose conflicting protein figures; no mixed-edition article.'}, {'candidate': 'Greggs breakfast with a drink as separate page', 'disposition': 'Consolidated into the substantial baguette comparison to avoid overlapping articles.'}]}
    (OUT / 'restaurants.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    return manifest


if __name__ == '__main__':
    result = export()
    print(json.dumps({'articles': len(result['articles']), 'sourceServings': result['existingSourceServingsUsed'], 'newMenuRecords': 0}))
